use std::collections::HashMap;

/// A trie (prefix tree) implementation supporting insert, search, and prefix listing.
#[derive(Debug, Default)]
pub struct Trie {
    root: TrieNode,
}

#[derive(Debug, Default)]
struct TrieNode {
    children: HashMap<char, TrieNode>,
    is_end_of_word: bool,
}

impl Trie {
    /// Creates a new empty Trie.
    pub fn new() -> Self {
        Trie {
            root: TrieNode::default(),
        }
    }

    /// Inserts a word into the trie.
    pub fn insert(&mut self, word: &str) {
        let mut node = &mut self.root;
        for ch in word.chars() {
            node = node.children.entry(ch).or_insert_with(TrieNode::default);
        }
        node.is_end_of_word = true;
    }

    /// Returns true if the exact word exists in the trie.
    pub fn search(&self, word: &str) -> bool {
        let mut node = &self.root;
        for ch in word.chars() {
            match node.children.get(&ch) {
                Some(next) => node = next,
                None => return false,
            }
        }
        node.is_end_of_word
    }

    /// Returns true if any word in the trie starts with the given prefix.
    pub fn starts_with(&self, prefix: &str) -> bool {
        let mut node = &self.root;
        for ch in prefix.chars() {
            match node.children.get(&ch) {
                Some(next) => node = next,
                None => return false,
            }
        }
        true
    }

    /// Returns all words in the trie that start with the given prefix.
    pub fn list_by_prefix(&self, prefix: &str) -> Vec<String> {
        let mut node = &self.root;
        for ch in prefix.chars() {
            match node.children.get(&ch) {
                Some(next) => node = next,
                None => return Vec::new(),
            }
        }
        let mut results = Vec::new();
        self._collect_words(node, &mut results, prefix);
        results
    }

    fn _collect_words(&self, node: &TrieNode, results: &mut Vec<String>, current: &str) {
        if node.is_end_of_word {
            results.push(current.to_string());
        }
        for (ch, child) in &node.children {
            let mut new_current = current.to_string();
            new_current.push(*ch);
            self._collect_words(child, results, &new_current);
        }
    }
}

