 * Trie (Prefix Tree) Implementation
 * Supports insert, search, and prefix listing operations.
 */

class TrieNode {
  constructor() {
    this.children = {};
    this.isEndOfWord = false;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  /**
   * Insert a word into the trie.
   * @param {string} word - The word to insert.
   */
  insert(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children[char]) {
        node.children[char] = new TrieNode();
      }
      node = node.children[char];
    }
    node.isEndOfWord = true;
  }

  /**
   * Search for a complete word in the trie.
   * @param {string} word - The word to search for.
   * @returns {boolean} True if the word exists, false otherwise.
   */
  search(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children[char]) {
        return false;
      }
      node = node.children[char];
    }
    return node.isEndOfWord;
  }

  /**
   * Check if any word in the trie starts with the given prefix.
   * @param {string} prefix - The prefix to check.
   * @returns {boolean} True if there is a word with the given prefix, false otherwise.
   */
  startsWith(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.children[char]) {
        return false;
      }
      node = node.children[char];
    }
    return true;
  }

  /**
   * List all words that start with the given prefix.
   * @param {string} prefix - The prefix to search for.
   * @returns {string[]} An array of words starting with the prefix.
   */
  listByPrefix(prefix) {
    const results = [];
    // First, navigate to the node corresponding to the prefix
    let node = this.root;
    for (const char of prefix) {
      if (!node.children[char]) {
        return results;
      }
      node = node.children[char];
    }
    // Now collect all words from this node
    this._collectWords(node, prefix, results);
    return results;
  }

  /**
   * Helper method to recursively collect all words from a given node.
   * @param {TrieNode} node - The current node.
   * @param {string} currentWord - The word built so far.
   * @param {string[]} results - The array to collect results into.
   */
  _collectWords(node, currentWord, results) {
    if (node.isEndOfWord) {
      results.push(currentWord);
    }
    for (const char in node.children) {
      this._collectWords(node.children[char], currentWord + char, results);
    }
  }
}

