   ```java
   public class Trie {
       private static class Node {
           Map<Character, Node> children = new HashMap<>();
           boolean isEndOfWord = false;
       }

       private Node root;

       public Trie() {
           root = new Node();
       }

       public void insert(String word) {
           Node curr = root;
           for (char c : word.toCharArray()) {
               curr.children.putIfAbsent(c, new Node());
               curr = curr.children.get(c);
           }
           curr.isEndOfWord = true;
       }

       public boolean search(String word) {
           Node curr = root;
           for (char c : word.toCharArray()) {
               if (!curr.children.containsKey(c)) return false;
               curr = curr.children.get(c);
           }
           return curr.isEndOfWord;
       }

       public boolean startsWith(String prefix) {
           Node curr = root;
           for (char c : prefix.toCharArray()) {
               if (!curr.children.containsKey(c)) return false;
               curr = curr.children.get(c);
           }
           return true;
       }

       public List<String> listPrefix(String prefix) {
           List<String> result = new ArrayList<>();
           Node curr = root;
           for (char c : prefix.toCharArray()) {
               if (!curr.children.containsKey(c)) return result;
               curr = curr.children.get(c);
           }
           collectWords(curr, prefix, result);
           return result;
       }

       private void collectWords(Node node, String prefix, List<String> result) {
           if (node.isEndOfWord) {
               result.add(prefix);
           }
           for (Map.Entry<Character, Node> entry : node.children.entrySet()) {
               collectWords(entry.getValue(), prefix + entry.getKey(), result);
           }
       }
   }
