fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        eprintln!("Usage: {} <filename>", args[0]);
        process::exit(1);
    }

    let filename = &args[1];

    let content = match fs::read_to_string(filename) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error reading file '{}': {}", filename, e);
            process::exit(1);
        }
    };

    let mut word_counts: HashMap<String, usize> = HashMap::new();

    for word in content.split_whitespace() {
        // Convert to lowercase and strip non-alphanumeric characters from edges
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .collect();

        if cleaned.is_empty() {
            continue;
        }

        // Normalize: lowercase the word
        let normalized = cleaned.to_lowercase();

        // Remove leading and trailing apostrophes for cleaner words
        let normalized = normalized.trim_matches('\'').to_string();

        if normalized.is_empty() {
            continue;
        }

        *word_counts.entry(normalized).or_insert(0) += 1;
    }

    let mut word_list: Vec<(String, usize)> = word_counts.into_iter().collect();

    // Sort by frequency descending, then by word ascending for tie-breaking
    word_list.sort_by(|a, b| {
        b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0))
    });

    let top_n = if word_list.len() > 20 { 20 } else { word_list.len() };

    for i in 0..top_n {
        let (word, count) = &word_list[i];
        println!("{}: {}", count, word);
    }
