#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Get the file path from command line arguments
const args = process.argv.slice(2);

if (args.length < 1) {
  console.error('Usage: node wordfreq.js <filename>');
  process.exit(1);
}

const filePath = args[0];

// Check if the file exists
if (!fs.existsSync(filePath)) {
  console.error(`Error: File '${filePath}' not found.`);
  process.exit(1);
}

// Read the file content
let content;
try {
  content = fs.readFileSync(filePath, 'utf-8');
} catch (err) {
  console.error(`Error reading file: ${err.message}`);
  process.exit(1);
}

// Process the text: split into words, convert to lowercase, filter out non-alphanumeric
const words = content
  .toLowerCase()
  .replace(/[^a-z0-9\s'-]/g, ' ')
  .split(/\s+/)
  .filter(word => word.length > 0);

// Count word frequencies
const frequencyMap = {};
for (const word of words) {
  // Clean up leading/trailing apostrophes and hyphens for better word boundaries
  const cleanedWord = word.replace(/^['-]+|['-]+$/g, '');
  if (cleanedWord.length > 0) {
    frequencyMap[cleanedWord] = (frequencyMap[cleanedWord] || 0) + 1;
  }
}

// Convert to array and sort by frequency (descending), then alphabetically for ties
const sortedWords = Object.entries(frequencyMap)
  .sort((a, b) => {
    if (b[1] !== a[1]) {
      return b[1] - a[1];
    }
    return a[0].localeCompare(b[0]);
  })
  .slice(0, 20);

// Print the top 20 words
console.log('Top 20 most frequent words:');
console.log('---------------------------');
sortedWords.forEach(([word, count], index) => {
  console.log(`${index + 1}. ${word}: ${count}`);
});
