    /// <summary>
    /// A generic Trie (prefix tree) implementation supporting insert, search, and prefix listing.
    /// </summary>
    /// <typeparam name="T">The type of data stored at each node. Default is string.</typeparam>
    public class Trie<T> where T : class
    {
        private class TrieNode
        {
            public bool IsEndOfWord { get; set; }
            public T? Data { get; set; }
            public Dictionary<char, TrieNode> Children { get; } = new Dictionary<char, TrieNode>();
        }

        private readonly TrieNode _root;

        public Trie()
        {
            _root = new TrieNode();
        }

        /// <summary>
        /// Inserts a word into the trie.
        /// </summary>
        /// <param name="word">The word to insert.</param>
        /// <param name="data">Optional data to associate with the word.</param>
        public void Insert(string word, T? data = null)
        {
            if (word == null)
                throw new ArgumentNullException(nameof(word));

            TrieNode current = _root;
            foreach (char c in word.ToLowerInvariant())
            {
                if (!current.Children.ContainsKey(c))
                {
                    current.Children[c] = new TrieNode();
                }
                current = current.Children[c];
            }
            current.IsEndOfWord = true;
            current.Data = data;
        }

        /// <summary>
        /// Searches for a complete word in the trie.
        /// </summary>
        /// <param name="word">The word to search for.</param>
        /// <returns>True if the word exists in the trie, false otherwise.</returns>
        public bool Search(string word)
        {
            if (word == null)
                throw new ArgumentNullException(nameof(word));

            TrieNode current = _root;
            foreach (char c in word.ToLowerInvariant())
            {
                if (!current.Children.ContainsKey(c))
                {
                    return false;
                }
                current = current.Children[c];
            }
            return current.IsEndOfWord;
        }

        /// <summary>
        /// Searches for a prefix in the trie.
        /// </summary>
        /// <param name="prefix">The prefix to search for.</param>
        /// <returns>True if the prefix exists in the trie, false otherwise.</returns>
        public bool SearchPrefix(string prefix)
        {
            if (prefix == null)
                throw new ArgumentNullException(nameof(prefix));

            TrieNode current = _root;
            foreach (char c in prefix.ToLowerInvariant())
            {
                if (!current.Children.ContainsKey(c))
                {
                    return false;
                }
                current = current.Children[c];
            }
            return true;
        }

        /// <summary>
        /// Lists all words in the trie that start with the given prefix.
        /// </summary>
        /// <param name="prefix">The prefix to search for.</param>
        /// <returns>A list of all words starting with the given prefix.</returns>
        public List<string> ListByPrefix(string prefix)
        {
            if (prefix == null)
                throw new ArgumentNullException(nameof(prefix));

            TrieNode current = _root;
            foreach (char c in prefix.ToLowerInvariant())
            {
                if (!current.Children.ContainsKey(c))
                {
                    return new List<string>();
                }
                current = current.Children[c];
            }

            var results = new List<string>();
            CollectWords(current, prefix, results);
            return results;
        }

        private void CollectWords(TrieNode node, string prefix, List<string> results)
        {
            if (node == null)
                return;

            if (node.IsEndOfWord)
            {
                results.Add(prefix);
            }

            foreach (var kvp in node.Children)
            {
                CollectWords(kvp.Value, prefix + kvp.Key, results);
            }
        }

        /// <summary>
        /// Lists all words in the trie.
        /// </summary>
        /// <returns>A list of all words in the trie.</returns>
        public List<string> ListAll()
        {
            var results = new List<string>();
            CollectWords(_root, "", results);
            return results;
        }
