                // Split by non-alphanumeric characters to get words
                // Convert to lowercase for case-insensitive counting
                var words = content.ToLower()
                    .Split(new char[] { ' ', '\t', '\n', '\r', '.', ',', ';', ':', '!', '?', '"', '\'', '(', ')', '[', ']', '{', '}', '-', '_', '/', '@', '#', '$', '%', '^', '&', '*', '+', '=', '|', '<', '>', '\\' }, 
                           StringSplitOptions.RemoveEmptyEntries);

                var wordCounts = new Dictionary<string, int>();

                foreach (string word in words)
                {
                    if (wordCounts.ContainsKey(word))
                    {
                        wordCounts[word]++;
                    }
                    else
                    {
                        wordCounts[word] = 1;
                    }
                }

                // Sort by frequency (descending), then alphabetically for ties
                var topWords = wordCounts.OrderByDescending(w => w.Value)
                                         .ThenBy(w => w.Key)
                                         .Take(20)
                                         .ToList();

                Console.WriteLine("Top 20 most frequent words:");
                Console.WriteLine(new string('-', 40));

                int rank = 1;
                foreach (var word in topWords)
                {
                    Console.WriteLine($"{rank}. {word.Key,-20} {word.Value,5}");
                    rank++;
                }
            }
