async function readAndValidateConfig(filePath) {
  const fs = require('fs').promises;

  let rawContent;
  try {
    rawContent = await fs.readFile(filePath, 'utf-8');
  } catch (err) {
    return { success: false, error: new Error(`Failed to read config file: ${err.message}`) };
  }

  let parsed;
  try {
    parsed = JSON.parse(rawContent);
  } catch (err) {
    return { success: false, error: new Error(`Invalid JSON in config file: ${err.message}`) };
  }

  if (typeof parsed.name !== 'string' || parsed.name.length === 0) {
    return { success: false, error: new Error('Config field "name" must be a non-empty string') };
  }

  if (typeof parsed.version !== 'string' || parsed.version.length === 0) {
    return { success: false, error: new Error('Config field "version" must be a non-empty string') };
  }

  if (typeof parsed.debug !== 'boolean') {
    return { success: false, error: new Error('Config field "debug" must be a boolean') };
  }

  return {
    success: true,
    data: {
      name: parsed.name,
      version: parsed.version,
      debug: parsed.debug
    }
  };
}

