   import java.io.BufferedReader;
   import java.io.FileReader;
   import java.io.IOException;
   import java.util.*;
   import java.util.regex.Pattern;
   import java.util.regex.Matcher;

   public class WordFrequencyCounter {
       public static void main(String[] args) {
           if (args.length != 1) {
               System.err.println("Usage: java WordFrequencyCounter <file_path>");
               System.exit(1);
           }

           String filePath = args[0];
           Map<String, Integer> frequencyMap = new HashMap<>();
           Pattern pattern = Pattern.compile("\\b[\\w']+\\b"); // \w includes letters, digits, underscore

           try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
               String line;
               while ((line = reader.readLine()) != null) {
                   Matcher matcher = pattern.matcher(line.toLowerCase());
                   while (matcher.find()) {
                       String word = matcher.group();
                       frequencyMap.merge(word, 1, Integer::sum);
                   }
               }
           } catch (IOException e) {
               System.err.println("Error reading file: " + e.getMessage());
               System.exit(1);
           }

           // Sort and get top 20
           List<Map.Entry<String, Integer>> sortedWords = new ArrayList<>(frequencyMap.entrySet());
           sortedWords.sort((a, b) -> {
               int freqCompare = b.getValue().compareTo(a.getValue());
               if (freqCompare != 0) return freqCompare;
               return a.getKey().compareTo(b.getKey()); // alphabetical tie-break
           });

           int limit = Math.min(20, sortedWords.size());
           System.out.println("Top " + limit + " most frequent words:");
           for (int i = 0; i < limit; i++) {
               Map.Entry<String, Integer> entry = sortedWords.get(i);
               System.out.printf("%-20s %d%n", entry.getKey(), entry.getValue());
           }
       }
   }
