#define MAX_WORD_LEN 256
#define MAX_WORDS 100000
#define TOP_N 20

typedef struct {
    char word[MAX_WORD_LEN];
    int count;
} WordCount;

// Comparison function for sorting by frequency (descending), then alphabetically for ties
int compare_by_count_desc(const void *a, const void *b) {
    const WordCount *wa = (const WordCount *)a;
    const WordCount *wb = (const WordCount *)b;
    if (wb->count != wa->count) {
        return wb->count - wa->count;
    }
    return strcmp(wa->word, wb->word);
}

// Comparison function for sorting alphabetically (ascending)
int compare_by_alpha(const void *a, const void *b) {
    const WordCount *wa = (const WordCount *)a;
    const WordCount *wb = (const WordCount *)b;
    return strcmp(wa->word, wb->word);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open file '%s'\n", argv[1]);
        return 1;
    }

    WordCount words[MAX_WORDS];
    int num_unique = 0;

    char buf[MAX_WORD_LEN];
    int ch;
    int i = 0;

    while ((ch = fgetc(fp)) != EOF) {
        if (isalpha(ch)) {
            if (i < MAX_WORD_LEN - 1) {
                buf[i++] = tolower((unsigned char)ch);
            }
        } else {
            if (i > 0) {
                buf[i] = '\0';

                // Check if word already exists
                int found = 0;
                for (int j = 0; j < num_unique; j++) {
                    if (strcmp(words[j].word, buf) == 0) {
                        words[j].count++;
                        found = 1;
                        break;
                    }
                }

                if (!found && num_unique < MAX_WORDS) {
                    strncpy(words[num_unique].word, buf, MAX_WORD_LEN - 1);
                    words[num_unique].word[MAX_WORD_LEN - 1] = '\0';
                    words[num_unique].count = 1;
                    num_unique++;
                }

                i = 0;
            }
        }
    }
    // Handle last word if file doesn't end with non-alpha
    if (i > 0) {
        buf[i] = '\0';
        int found = 0;
        for (int j = 0; j < num_unique; j++) {
            if (strcmp(words[j].word, buf) == 0) {
                words[j].count++;
                found = 1;
                break;
            }
        }
        if (!found && num_unique < MAX_WORDS) {
            strncpy(words[num_unique].word, buf, MAX_WORD_LEN - 1);
            words[num_unique].word[MAX_WORD_LEN - 1] = '\0';
            words[num_unique].count = 1;
            num_unique++;
        }
    }

    fclose(fp);

    if (num_unique == 0) {
        printf("No words found in the file.\n");
        return 0;
    }

    // Sort by frequency descending, then alphabetically
    qsort(words, num_unique, sizeof(WordCount), compare_by_count_desc);

    int top = num_unique < TOP_N ? num_unique : TOP_N;

    printf("Top %d words by frequency:\n", top);
    for (int i = 0; i < top; i++) {
        printf("%d. %s: %d\n", i + 1, words[i].word, words[i].count);
    }

    return 0;
}
