/// Computes the Levenshtein distance between two strings using O(n) memory,
/// where n is the length of the second string.
///
/// The Levenshtein distance is the minimum number of single-character edits
/// (insertions, deletions, or substitutions) required to change one string
/// into the other.
///
/// This implementation uses a space-optimized dynamic programming approach.
/// Instead of storing the full DP table of size (m+1) x (n+1), we only keep
/// two rows: the previous row and the current row. This reduces space
/// complexity from O(m*n) to O(n), where m and n are the lengths of the
/// two input strings.
///
/// The DP recurrence is:
///   dp[i][j] = 0 if i == 0 and j == 0
///   dp[i][0] = i if j == 0 (deleting i characters from first string)
///   dp[0][j] = j if i == 0 (inserting j characters into first string)
///   dp[i][j] = dp[i-1][j-1] if s1[i-1] == s2[j-1] (no edit needed)
///   dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) otherwise
///     where dp[i-1][j] represents deletion,
///           dp[i][j-1] represents insertion,
///           dp[i-1][j-1] represents substitution.
///
/// By keeping only two rows, we can compute each row from the previous one
/// in O(n) space.
///
/// # Arguments
/// * `s1` - The first string
/// * `s2` - The second string
///
/// # Returns
/// The Levenshtein distance between `s1` and `s2`
pub fn levenshtein_distance(s1: &str, s2: &str) -> usize {
    let s1_bytes = s1.as_bytes();
    let s2_bytes = s2.as_bytes();
    let m = s1_bytes.len();
    let n = s2_bytes.len();

    // If either string is empty, the distance is the length of the other string
    if m == 0 {
        return n;
    }
    if n == 0 {
        return m;
    }

    // We use two rows: `prev` and `curr`
    // prev[j] will store dp[i-1][j], the previous row
    // curr[j] will store dp[i][j], the current row being computed
    let mut prev: Vec<usize> = (0..=n).collect();
    let mut curr: Vec<usize> = vec![0; n + 1];

    for i in 1..=m {
        // Base case: dp[i][0] = i (deleting i characters from s1 to match empty s2)
        curr[0] = i;

        for j in 1..=n {
            if s1_bytes[i - 1] == s2_bytes[j - 1] {
                // Characters match: no edit needed, take diagonal value
                curr[j] = prev[j - 1];
            } else {
                // Take the minimum of:
                // - prev[j]: deletion from s1
                // - curr[j-1]: insertion into s1 (or deletion from s2)
                // - prev[j-1]: substitution
                let deletion = prev[j];
                let insertion = curr[j - 1];
                let substitution = prev[j - 1];
                curr[j] = 1 + deletion.min(insertion).min(substitution);
            }
        }

        // Move current row to previous for the next iteration
        // Swap references to avoid copying the entire vector
        std::mem::swap(&mut prev, &mut curr);
    }

    // After the loop, the last computed row is in `prev` because of the swap
    prev[n]
}

