#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/**
 * Compute the Levenshtein distance between two strings.
 * 
 * Levenshtein distance is the minimum number of single-character edits
 * (insertions, deletions, or substitutions) required to change one string
 * into another.
 * 
 * This implementation uses O(min(m, n)) memory by keeping only the previous
 * and current rows of the dynamic programming table, since each row only
 * depends on the previous row.
 * 
 * @param s1 First string
 * @param s2 Second string
 * @return The Levenshtein distance between s1 and s2
 */
int levenshtein_distance(const char *s1, const char *s2) {
    if (s1 == NULL || s2 == NULL) {
        return -1; // Error: null input
    }

    int m = strlen(s1);
    int n = strlen(s2);

    // If one string is empty, the distance is the length of the other
    if (m == 0) return n;
    if (n == 0) return m;

    // Ensure we use the shorter string for the column dimension to minimize memory
    // We'll swap if necessary so that n <= m, meaning we allocate space for n+1
    // But actually, the standard optimization is to keep only two rows.
    // Let's keep the column size as n+1 (for s2's length) and iterate over s1's rows.
    // Memory: O(n) where n = strlen(s2)

    // Allocate two rows: previous and current
    int *prev = (int *)malloc((n + 1) * sizeof(int));
    int *curr = (int *)malloc((n + 1) * sizeof(int));

    if (prev == NULL || curr == NULL) {
        free(prev);
        free(curr);
        return -1; // Memory allocation error
    }

    // Initialize the first row: distance from empty string s1[0..0] to s2[0..j]
    // This is simply j (j insertions)
    for (int j = 0; j <= n; j++) {
        prev[j] = j;
    }

    // Fill the DP table row by row
    for (int i = 1; i <= m; i++) {
        // Initialize the first column: distance from s1[0..i] to empty string s2
        // This is i (i deletions)
        curr[0] = i;

        for (int j = 1; j <= n; j++) {
            if (s1[i - 1] == s2[j - 1]) {
                // Characters match: no operation needed, carry forward the diagonal value
                curr[j] = prev[j - 1];
            } else {
                // Characters differ: take the minimum of three possible operations:
                // 1. Deletion: prev[j] + 1     (delete s1[i-1])
                // 2. Insertion: curr[j-1] + 1   (insert s2[j-1])
                // 3. Substitution: prev[j-1] + 1 (replace s1[i-1] with s2[j-1])
                int deletion = prev[j] + 1;
                int insertion = curr[j - 1] + 1;
                int substitution = prev[j - 1] + 1;

                // Find the minimum
                curr[j] = deletion;
                if (insertion < curr[j]) {
                    curr[j] = insertion;
                }
                if (substitution < curr[j]) {
                    curr[j] = substitution;
                }
            }
        }

        // Move current row to previous for the next iteration
        // Swap pointers instead of copying to save time
        int *temp = prev;
        prev = curr;
        curr = temp;
    }

    // After the loop, prev holds the last computed row (distance to s1[0..m])
    int result = prev[n];

    // Clean up allocated memory
    free(prev);
    free(curr);

    return result;
}
