using System;

/// <summary>
/// Computes the Levenshtein distance between two strings using O(n) memory,
/// where n is the length of the shorter string.
/// 
/// The Levenshtein distance is the minimum number of single-character edits
/// (insertions, deletions, or substitutions) required to change one string
/// into another.
/// 
/// Algorithm:
/// We use the classic dynamic programming approach but optimize space by
/// keeping only two rows of the DP table at a time: the previous row and
/// the current row. This reduces space complexity from O(m*n) to O(min(m,n)).
/// 
/// Let m be the length of string1 and n be the length of string2.
/// We ensure that the second string is the shorter one to minimize space.
/// 
/// DP recurrence:
///   dp[i][j] = dp[i-1][j-1]           if string1[i] == string2[j]
///   dp[i][j] = 1 + min(dp[i-1][j-1],   if string1[i] != string2[j]
///                       dp[i-1][j],
///                       dp[i][j-1])
/// 
/// We only need the previous row to compute the current row, so we maintain
/// two arrays: 'prev' and 'curr', each of size n+1.
/// 
/// Time Complexity: O(m * n)
/// Space Complexity: O(min(m, n))
/// </summary>
/// <param name="str1">The first string.</param>
/// <param name="str2">The second string.</param>
/// <returns>The Levenshtein distance between str1 and str2.</returns>
public static int LevenshteinDistance(string str1, string str2)
{
    // Handle edge cases
    if (str1 == null && str2 == null)
        return 0;
    if (str1 == null)
        return str2.Length;
    if (str2 == null)
        return str1.Length;

    int m = str1.Length;
    int n = str2.Length;

    // Ensure that we use the shorter string for the DP array to minimize space
    if (n > m)
    {
        // Swap so that str2 is the shorter string
        string temp = str1;
        str1 = str2;
        str2 = temp;
        int tempInt = m;
        m = n;
        n = tempInt;
    }

    // prev[j] holds the values for the previous row (i-1)
    // curr[j] holds the values for the current row (i)
    int[] prev = new int[n + 1];
    int[] curr = new int[n + 1];

    // Initialize the first row: distance from empty string to str2[0..j]
    // This corresponds to inserting j characters
    for (int j = 0; j <= n; j++)
    {
        prev[j] = j;
    }

    // Fill the DP table row by row
    for (int i = 1; i <= m; i++)
    {
        // Initialize the first column: distance from str1[0..i] to empty string
        // This corresponds to deleting i characters
        curr[0] = i;

        for (int j = 1; j <= n; j++)
        {
            if (str1[i - 1] == str2[j - 1])
            {
                // Characters match: no additional cost
                curr[j] = prev[j - 1];
            }
            else
            {
                // Characters differ: take the minimum of three operations
                // +1 for substitution (prev[j-1]), deletion (prev[j]), or insertion (curr[j-1])
                int substitution = prev[j - 1];
                int deletion = prev[j];       // Delete from str1 (move down in str1)
                int insertion = curr[j - 1];  // Insert into str1 (move right in str2)

                curr[j] = 1 + Math.Min(substitution, Math.Min(deletion, insertion));
            }
        }

        // Move current row to previous for the next iteration
        // Swap references instead of copying
        int[] tempArray = prev;
        prev = curr;
        curr = tempArray;
    }

    // After the loop, the answer is in prev[n] because we swapped at the end
    return prev[n];
}
