func main() {
	// 定义命令行参数
	filename := flag.String("f", "", "要统计的文件路径（必填）")
	limit := flag.Int("n", 10, "显示前N个最高频的单词（默认10）")
	caseSensitive := flag.Bool("case", false, "是否区分大小写（默认不区分）")
	flag.Parse()

	// 验证输入参数
	if *filename == "" {
		fmt.Fprintf(os.Stderr, "错误：请指定文件路径，使用 -f 参数\n")
		fmt.Fprintf(os.Stderr, "用法: wordfreq -f <文件路径> [-n <数量>] [-case]\n")
		os.Exit(1)
	}

	// 打开文件
	file, err := os.Open(*filename)
	if err != nil {
		fmt.Fprintf(os.Stderr, "错误：无法打开文件 %s: %v\n", *filename, err)
		os.Exit(1)
	}
	defer file.Close()

	// 统计词频
	wordCounts := countWords(file, *caseSensitive)

	// 按词频降序排序
	sorted := sortByFrequency(wordCounts)

	// 取前 N 个
	if *limit > len(sorted) {
		*limit = len(sorted)
	}
	topWords := sorted[:*limit]

	// 输出结果
	fmt.Println("=== 词频统计结果 ===")
	fmt.Printf("文件: %s\n", *filename)
	fmt.Printf("显示前 %d 个高频词\n\n", *limit)

	for i, wc := range topWords {
		// 使用制表符对齐，左对齐单词，右对齐数字
		fmt.Printf("%3d. %-20s %d 次\n", i+1, wc.Word, wc.Count)
	}

	// 输出总词数
	total := 0
	for _, wc := range wordCounts {
		total += wc.Count
	}
	fmt.Printf("\n总词数: %d\n", total)
}

